        'ZCB0dXBsZSBvZiBjYWxsYWJsZXMgcmV0dXJuaW5nIFRydWU7IHN0b3BzIGF0IHRoZSBmaXJzdCBu',
        'b24tVHJ1ZSAobm8gcmV0cmllcykuIiIiCiAgICBfbmVlZCh0eXBlKGNoZWNrcykgaXMgdHVwbGUg',
        'YW5kIDEgPD0gbGVuKGNoZWNrcykgPD0gMzIgYW5kIGFsbChjYWxsYWJsZShjKSBmb3IgYyBpbiBj',
        'aGVja3MpKQoKICAgIGRlZiB1YXQoKToKICAgICAgICBmb3IgY2hlY2sgaW4gY2hlY2tzOgogICAg',
